function sceneChanged(message){initialPositions=null;selected=-1;invalidateTimeline(message);resetWorld();edited();renderer?.draw(world,state);}
$('text-unit').onchange=()=>{state.textMode=$('text-unit').value;state.freeRotation=state.textMode==='block';state.typeSizeReferenceRadius=Math.max(.001,E.radius(state,width,height,E.letters(textValue(),state.textMode).length));overrides={};inkOverrides={};sceneChanged('텍스트 단위가 바뀌어');rebuildText(false);};
$('space-mode').onchange=()=>{const mode=$('space-mode').value;state.openTop=mode==='top';state.flowThrough=mode==='through';if(mode!=='through'){state.repeatFlight=false;if(['below','filled'].includes(state.startMode))state.startMode='arranged';}if(mode!=='closed')state.wallBounce=false;sceneChanged('공간이 바뀌어');};
$('motion-mode').onchange=()=>{const mode=$('motion-mode').value;state.wallBounce=mode==='bounce';state.hold=mode==='held';if(state.wallBounce){state.openTop=false;state.flowThrough=false;state.repeatFlight=false;if(['below','filled'].includes(state.startMode))state.startMode='arranged';}sceneChanged('움직임 방식이 바뀌어');};
$('start-mode').onchange=()=>{state.startMode=$('start-mode').value;if(['below','filled'].includes(state.startMode)){state.flowThrough=true;state.openTop=false;state.wallBounce=false;}if(state.startMode==='filled')state.repeatFlight=true;if(state.startMode==='random'&&!state.startSeed)state.startSeed=1+Math.floor(Math.random()*2147483000);edited();};
$('apply-start').onclick=()=>{if(state.startMode==='random')state.startSeed=1+Math.floor(Math.random()*2147483000);sceneChanged('시작 위치가 바뀌어');paused=false;syncUI();};
$('startSpread').oninput=()=>{state.startSpread=Number($('startSpread').value);state.startMode='random';if(!state.startSeed)state.startSeed=1+Math.floor(Math.random()*2147483000);sceneChanged('시작 범위가 바뀌어');};
$('repeatFlight').onchange=()=>{state.repeatFlight=$('repeatFlight').checked;if(!state.repeatFlight&&state.startMode==='filled')state.startMode='arranged';sceneChanged('반복 방식이 바뀌어');};
$('background').oninput=$('background').onchange=()=>{state.background=$('background').value;state.backgroundGradient=false;edited();renderer?.draw(world,state);};
$('studio-preset-apply').onclick=async()=>{if(exporting||fontBusy)return;const key=$('studio-preset').value;try{if(key==='basic'){await $('reset-defaults').onclick();}else await applyProject(studioPresets[key]);paused=false;syncUI();notice('시작 프리셋을 적용했어요. 각 설정을 자유롭게 바꿀 수 있어요.');}catch(e){notice(e.message,true);}};
syncUnified();

